import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { extendSquizLink } from "@ntgovernment/squiz-factory/utils/squiz-links";
import stableId from "@ntgovernment/squiz-factory/utils/stableId";

const ALERT_TYPE_CLASS = {
  Info: "info",
  Warning: "warning",
  Critical: "critical",
  "Info-alt": "info-alt",
};

export default {
  async main(input, info) {
    const debug = ''; // `<!-- ${JSON.stringify(input, null, 2)} -->\n`;
    return `${debug}<div data-component="global-alerts">${input?.alerts?.length
        ? `<div class="content-area">
            ${input.alerts.map((alert) => renderAlert(alert, info)).join("\n")}
          </div>
        </div>`
        : "<!-- no alerts set -->"
    }`;
  },
};

function renderAlert(input, info) {
  const alertId = stableId(input, info);
  const {
    alertType,
    message,
    actions,
    dismissible,
  } = input;

  const type = ALERT_TYPE_CLASS[alertType] || "info";
  const dismissType = dismissible.startsWith("Session") ? 'session' : dismissible.startsWith('Local') ? 'local' : null;
  const links = actions
    .map(extendSquizLink)
    .map(link => `<a class="button button-secondary button-sm" ${link.attrs}>${escHTML(link.text)}</a>`);

  const actionHtml = actions.length
    ? `<div class="global-alert__action">${links.join('')}</div>`
    : "";

  const dismissHtml = dismissType
    ? `<button type="button" class="global-alert__dismiss" aria-label="Dismiss alert">
        <i class="fa-light fa-xmark"></i>
      </button>`
    : "";

  return /*html*/ `
  <div class="global-alert global-alert--${type} content ${type === 'info-alt' ? '' : 'with-mono-links'}" data-cc="fullwidth background" data-global-alert-id="${alertId}" ${dismissType ? `data-dismissible="${dismissType}"` : ""} role="region">
    <div class="global-alert__content">
      ${message}
      ${actionHtml}
    </div>
    ${dismissHtml}
  </div>
  `;
}
