import squizStoryRenderer from "@ntgovernment/squiz-factory/plugins/squizStoryRenderer";
import { html } from "lit";
import comp from "./main.js";
import defaultArgs from "./previews/default.data.json";

const squiz = squizStoryRenderer(comp.main);

export default {
  title: "dxp components/Global Alert",
  parameters: {
    noContentArea: true,
    controls: {
      expanded: true,
      sort: "requiredFirst",
    },
  },
};

const defaultHtml = await squiz.markup(defaultArgs);

const resetStore = () => {
  sessionStorage.removeItem('global-alerts');
  localStorage.removeItem('global-alerts');
};

export const Default = {
  render: (args) => {
    requestAnimationFrame(() => {
      resetStore();
      window.__ntgds__?.run?.('global-alerts');
    });
    const input = {
      alerts: [
        {
          ...args,
          actions: [args.actions]
        },
        ...(defaultArgs.alerts || []),
      ]
    }
    return squiz(input);
  },
  args: {
    alertType: 'info-alt',
    message: 'Hello',
    actions: {url: "#!hello", text: 'Hello'},
    dismissible: "NO"
  },
  argTypes: {
    alertType: { control: "select", options: ["Info", "Warning", "Critical", "Info-alt"] },
    message: { control: "text" },
    actions: { control: "object", description: 'SquizLink object: { text, url, target? }.' },
    dismissible: { 
      control: "select",
      options: ["NO", "Session", "Local"]
    }
  },
  parameters: {
    docs: {
      description: { story: "Info variant, with an inline link at the end of the message." },
      source: { code: defaultHtml, language: "html", type: "code" },
    },
  },
};
