const HOSTNAME_SCOPE = "hostname";
export default function stableId(value, info, scope = HOSTNAME_SCOPE) {
    const url = new URL(info?.ctx?.url ?? info?.url ?? "nope://nope.nope")[scope === HOSTNAME_SCOPE ? scope : "href"];
    const id = info?.ctx?.assetId ?? info?.assetId ?? "";
    const str = JSON.stringify({ value, url, id });
    let hash = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) {
        hash = Math.imul(hash ^ str.charCodeAt(i), 0x01000193);
    }
    return (hash >>> 0).toString(36);
}
